package com.harsh.desicrics

import android.app.Application
import com.harsh.desicrics.auth.GoogleSignInConfig
import com.harsh.desicrics.data.api.ApiConfig
import com.harsh.desicrics.di.initKoin
import org.koin.android.ext.koin.androidContext
import org.koin.dsl.module

class DesiCricsApp : Application() {
    override fun onCreate() {
        super.onCreate()
        initKoin {
            androidContext(this@DesiCricsApp)
            modules(
                module {
                    // Generated by the google-services plugin from google-services.json.
                    single { GoogleSignInConfig(webClientId = getString(R.string.default_web_client_id)) }
                    single { ApiConfig(baseUrl = BuildConfig.API_BASE_URL) }
                },
            )
        }
    }
}
